      "e": "本题考查西方文学-17 世纪文学-莫里哀。法国古典主义喜剧代表莫里哀的《吝啬鬼》（又译《悭吝人》）揭露和批判了资产阶级拜金主义的本性。作者用夸张讽刺的手法，成功塑造了“阿巴贡”这个典型的资产阶级守财奴形象。《妇人学堂》、《恨世者》、《史嘉本的诡计》均为莫里哀的作品，但没有塑造阿巴贡这个人物角色。"
