      "e": "本题考查西方文学-19 世纪文学（一）-概述。英国浪漫主义代表诗人雪莱，被恩格斯称为“天才的预言家”，作品有诗剧《解放了的普罗米修斯》、政治长诗《“虐政”的假面游行》、《给英国人民的歌》、描写自然景物的名篇《西风颂》、《致云雀》、《云》。雨果是法国浪漫主义文学的领导者，也是整个西方浪漫主义文学的集大成者。其剧作《欧那尼》标志着浪漫主义在法国最终战胜了古典主义，《巴黎圣母院》是其浪漫主义小说代表作，《悲惨世界》是其现实主义的代表作。拜伦是19 世纪英国和欧洲浪漫主义文学代表作家，作品中的典型形象被称为“拜伦式英雄”，代表作是《东方叙事诗》和《唐璜》。济慈，19 世纪初期英国诗人，浪漫派的主要成员，作品有《伊莎贝拉》《圣艾格尼丝之夜》《海壁朗》《夜莺颂》《希腊古瓮颂》《秋颂》等。"
