      "e": "本题考查西方文学-19 世纪文学（二）-斯丹达尔。斯丹达尔被誉为“近代小说之父”，塑造了一些“意大利性格”的人物。斯丹达尔著文为浪漫派辩护，抨击古典主义，他把文章汇成小册子，以《拉辛与莎士比亚》书名出版。《拉辛与莎士比亚》被誉为法国批判现实主义的文学宣言。普罗斯佩·梅里美，法国现实主义作家，剧作家，历史学家。主要作品有收集出版的剧本集《克拉拉·加苏尔戏剧集》（包括五个剧本）和历史剧《雅克团》，有长篇小说《查理九世的轶事》和中、短篇小说《马特奥·法尔哥内》《攻占棱堡》《塔曼果》《高龙巴》《卡门》《伊尔的美神》等。奥诺雷·德·巴尔扎克，法国小说家，被称为“现代法国小说之父”。乔治·桑，法国著名小说家，是巴尔扎克时代最具风情、最另类的小说家。她凭借发表的第一部长篇小说《安蒂亚娜》（1832）而一举成名。"
