      "e": "本题考查西方文学-20 世纪文学（一）-概述。1953 年苏联政局发生巨大变化。同样，文坛上创作思想空前活跃，很快形成了一股后来被称之为“解冻”的文学思潮。“解冻”的思潮是以爱伦堡的中篇小说《解冻》命名的。格罗斯曼，苏联作家，作品有长篇小说《斯捷潘·柯尔楚金》、中篇小说《人民是不朽的》、长篇小说《为了正义的事业》，1961 年写成长篇小说《生活与命运》，对苏联的政治社会生活与个人命运有深入的反思，被认为是20 世纪苏联文学的重要作品。亚历山大·索尔仁尼琴，俄罗斯作家，1968 年因作品《第一圈》无法在国内出版而在境外发表，被开除出作协，随后获得1970 年诺贝尔奖，而后因出版描写极权主义的巨著《古拉格群岛》被驱逐出国。法捷耶夫，苏联著名作家，是苏联社会主义现实主义文学的杰出代表之一。"
