     "a": "（1）肯定法国大革命的必然性与正义性，反对革命暴力和大规模的群众运动。反映了当时英国社会的尖锐矛盾、贫富的悬殊，下层群众中普遍存在着的愤懑与不满，指出这与大革命前的法国类似，警告英国统治者提防发生类似法国大革命的悲剧。（2）宣扬仁爱、宽恕，塑造了梅尼特、代尔那、卡尔登等一系列道德高尚的人物。（3）人道主义贯穿狄更斯创作的始终，是评价人物和各种现象的基本出发点。\n人道主义的基础与出发点：人性；主要内容：宽恕、爱、和解等；社会观察和评价的结果：社会批判。"
