     "a": "《哈姆莱特》：莎士比亚代表作。丹麦王子为父复仇的故事取材12世纪末的丹麦史。\n(1) 以中世纪的丹麦宫廷为背景，通过哈姆莱特为父复仇的故事，借古喻今，真实地描绘了文艺复兴运动晚期欧洲和英国社会的现状及矛盾。\n(2) 宫廷尔虞我诈，社会民怨沸腾，人文主义理想在这个罪恶当道的社会已无法实现。新旧社会力量和思想之间也进行着激烈的交锋，而新的社会力量和思想观念内部，也存在着善和恶两种力量的冲突和较量[新兴资产阶级—极端利己主义]，信仰的危机导致人们对人性本质的怀疑。\n(3) 表现了作者对文艺复兴运动的深刻反思以及对人的命运和社会未来的关注和忧虑。\n论述《哈姆莱特》的思想价值。【2204论述题答案】【★★★★】\n(1) 将哈姆莱特塑造为一个处于理想与现实矛盾中的人文主义者形象。\n(2) 哈姆莱特复仇的延宕，反映了欧洲文艺复兴晚期信仰失落时人们进退两难的矛盾心理。\n(3) 哈姆莱特对人性的思考，成为近代以来欧洲文学思考人性问题的开端。"
