     "a": "(1) 古典主义是17世纪法国形成的文学思潮。\n(2) 政治上拥护王权，维护国家民族的利益。 (3) 哲学上推崇理性，对理性的绝对遵从。\n(4) 戏剧创作模仿古人，重视创作规则。影响最大的是“三一律”。"
