     "a": "(1) 在古典主义戏剧的创作规则中，影响最大的是“三一律”。[“三一律”是古典主义戏剧的创作规则]\n(2) “三一律”要求一个剧本只能有一个情节线索，剧情只能发生在同一地点，时间不准超过一昼夜，24小时。"
