     "a": "(1)《熙德》：表现罗狄克与施曼娜在义务与爱情、理智与感情之间的矛盾与冲突，宣扬国家民族利益高于一切的思想。 (2) 只有得到理性控制而非盲目服从感情的摆布，才可能获得生活的幸福。\n(3)《熙德》是古典主义的第一部典范作品，也是古典主义戏剧的奠基作。没完全遵从“三一律”。"
