     "a": "(1) 都是百万字以上的鸿篇巨制，比一般的长篇小说容量更大，展现社会生活画卷更广泛。\n(2) 描写的往往是整整一代人或几代人的生活与精神面貌，再现法国社会、整个西欧社会的风貌和时代风云，作品具有史诗的壮阔性、历史的深刻性和反映现实生活的宏观性。\n(3) 代表是罗曼·罗兰的《约翰·克里斯朵夫》、马丁·杜·伽尔的《蒂博一家》。\n(4) 罗曼·罗兰：法国著名作家，伟大的人道主义者和社会活动家。多部著名人物传记：《贝多芬传》《米开朗基罗传》《托尔斯泰传》《甘地传》。4卷本长篇《欣悦的灵魂》、10卷本长篇小说《约翰·克里斯多夫》都是法国“长河小说”的杰作，《约翰·克里斯多夫》是罗曼·罗兰的代表作。主人公约翰·克里斯多夫是平民音乐家，也是有着鲜明个人主义色彩的英雄，通过他一生反抗、失败、妥协的经历和遭遇，抨击了艺术因依附于金钱与权势而导致的虚伪与堕落。"
