     "a": "(1) 巴威尔·符拉索夫从一个缺乏阶级意识的工人，成长为具有无产阶级觉悟的新人，每一个步履都洋溢着对未来的憧憬，对阶级力量和智慧的赞美。\n(2) 整部作品都在写人的成长，表现觉醒后的无产阶级革命者可以焕发出多么大的力量去完成他的历史使命。\n(3) 符拉索夫的形象，启迪人们憎恶旧社会，而且激发人们向往新生活。在高尔基笔下，无产阶级的社会理想被具体化为生动的艺术形象，无产阶级革命者的英雄形象。"
