     "a": "(1) 一个普通战士安德烈·索科洛夫的故事。他在卫国战争中经受了集中营生活的考验和亲人相继死亡的痛苦，在非人的环境里他保持了一个战士的高尚品质。战后他收养了一个孤儿，两个人相依为命，继续生活下去。\n(2) 是对苏联战士不可摧毁的坚毅精神的讴歌，但已不同于从前的玫瑰色的英雄主义，而是关于战争苦难的倾诉，是从人道主义的立场对于战争、对于既往历史的深入思考；为处理战争题材的文学作品开辟了新道路。"
