     "a": "(1) 赞颂人民在与邪恶势力斗争中所表现出的惊人智慧和才能。 (2) 揭露了统治者贪婪丑恶的本质。\n(3) 讴歌青年男女之间正当、纯洁的爱情。\n(4) 反映广大人民普遍置身其中的艰苦环境，尤其是商人经商冒险的生活。描写爱情自由和婚姻幸福；商人生活和海外冒险故事；底层人民的悲惨处境，揭露统治阶级穷奢极欲的生活。"
