     "h": "第一章（西方文学）古代文学",
     "c": "【小蒋老师说：本资料在以往考期基础上微调，篇幅内容有限，复习需用小蒋制作笔记和简答总结】\n      古希腊流传下来的最早一部以现实生活为题材的诗作是（《工作与时日》）。\n古希腊文学 古希腊最早的较系统地叙述关于宇宙起源和神的谱系的作品是（《神谱》）。\n 发展概况  文艺理论的代表作《诗学》的作者是（亚里士多德）。希腊化时期最著名的新喜剧作家是（米南德）。\n★★★★★ 新喜剧：古希腊“希腊化”时期的喜剧。以描写爱情故事和家庭关系为主要内容。作家米南德。\n         简述古希腊文学的特征。【1310 简答】\n      （1）鲜明的人本色彩和命运观念。 （2）现实主义与浪漫主义并存。（3）种类繁多，具有开创性。\n      古罗马最伟大的诗人是（维吉尔）。维吉尔的主要作品（《牧歌》、《埃涅阿斯纪》、《农事诗》）。\n      哲理长诗《物性论》的作者是（卢克莱修）。古罗马神话诗《变形记》的作者是（奥维德）。\n古罗马文学\n      贺拉斯关于文学的论文是（《诗艺》）。提出“寓教于乐”原则的古罗马诗人是（贺拉斯）。\n 发展概况\n      古罗马阿普列尤斯的小说：《金驴记》。古罗马奥古斯都时期的三大诗人：维吉尔、贺拉斯、奥维德。\n ★★★★\n       《埃涅阿斯纪》：【1704 名词】《埃涅阿斯纪》是维吉尔的代表作，是欧洲文人史诗的开端，也是世\n      界文学史上第一部文人史诗。作品主要颂扬罗马帝国的神圣，表现先王建国的艰辛。\n      古希腊神话包括（神的故事、英雄传说）。   宙斯（众神之主）\n 希腊神话  奥林波斯神系：希腊神话中的太阳神是（阿波罗）。希腊神话中地母的名字是（该亚）。\n  内容   古希腊神话中的智慧女神是（雅典娜）。古希腊神话中爱与美之神的名字是（阿佛洛狄忒）。\n★★★★★  简述古希腊神话的特点。【2210 简答】  （1）神是高度人格化的，神、人同形同性。\n       （2）体现出浓郁的人本主义色彩。     （3）想象丰富、内容生动、故事优美。\n      荷马史诗中塑造的英雄有（阿喀琉斯、奥德修斯、赫克托耳、阿伽门农）。\n      《伊利昂纪》围绕的结构线索是（阿喀琉斯的两次发怒），最勇猛的希腊联军主将是（阿喀琉斯）。\n      《伊利昂纪》是描写部落战争的英雄史诗。古希腊人对特洛伊战争的起因所做的神话性解释是不和的\n      金苹果。  反映氏族社会末期至奴隶社会初期人类对自然和社会斗争的史诗是（《奥德修纪》）。\n      《奥德修纪》突出的主题是（冒险精神）。荷马史诗中的奥德修斯是（理想化的早期奴隶主）。\n         论述《荷马史诗》的艺术成就：思想意义和艺术价值。【1804 论述】\n         两部史诗反映的基本思想：表现了人在自然及神斗争的过程中，人的奋斗精神、进取精神和人的\n        决定因素。也反映了当时社会的政治、经济、文化、风俗等各方面情况。颂扬了在奴隶制初期形\n 荷马史诗\n        成的这种新的家庭生活伦理道德风尚及一夫一妻制。\n         《荷马史诗》的艺术价值：\n★★★★★\n       （1）结构紧凑、安排巧妙。对于两个10 年中所发生的事，分别只表现了其中51 天和40 天中的内容。\n      （2）史诗塑造了众多英雄形象。【小蒋提醒：此处可分析：阿喀琉斯、奥德修斯、赫克托耳的形象】\n       如希腊主将阿喀琉斯是男性美的典范，集年轻/美貌/勇敢/钟情/义气/凶狠/善良于一身，性格立体多元。\n      （3）史诗的诗句流畅、自然优美、比喻生动形象，借动植物来喻人。后人赞誉“荷马式的比喻”。还\n      有固定的程式化的形容词和称谓。  （4）荷马史诗是欧洲文学中最优秀的作品，在世界文学史上享\n      有崇高的地位，被誉为“希腊人由野蛮时代进入文明时代的主要遗产。”\n         简析荷马史诗中的奥德修斯形象。【1610 简答】\n      （1）他是被理想化了的早期奴隶主形象。（2）英勇顽强、智慧过人的英雄形象。（3）他是性格复杂\n      的人物，不为荣华富贵所动，美女的诱惑动摇不了他对妻子的感情，但又不乏残酷、狡猾和自私。（4）\n      史诗肯定了他维护私有财产和一夫一妻这种新的社会制度所作的斗争，体现了人的个人意识的觉醒。\n         分析阿喀琉斯的形象。【1810 简答】\n      （1）希腊英雄阿喀琉斯是最具鲜明个性的形象。他是神与人之子，是男性美的典范。\n      （2）他的性格是立体多元的，集勇敢、义气、暴躁、凶狠、善良、诚挚于一身。\n      （3）为了部落集体的利益，他作战勇猛过人，表现出死而无怨的英雄主义精神。维护个人荣誉和尊严。\n         荷马史诗：【2504 名词】\n      （1）包括《伊利昂纪》和《奥德修纪》,是古希腊最早的两部史诗，相传由诗人荷马所作。\n      （2）前者写部落战争，后者写战争结束后，奥德修斯在海上漂流10 年期间发生的故事。\n      古希腊悲剧诗人有（埃斯库罗斯、索福克勒斯、欧里庇得斯）。古希腊戏剧的起源是（酒神祭祀）。\n      被誉为古希腊“悲剧之父”的诗人是（埃斯库罗斯）。\n      被誉为“戏剧艺术的荷马”的古希腊悲剧诗人是（索福克勒斯）。\n      被称为“舞台上的哲学家”的古希腊悲剧作家是（欧里庇得斯）。\n古希腊悲剧 同情妇女、为妇女鸣不平，对男女不平等进行批判的古希腊戏剧是（《美狄亚》）。\n ★★★★    索福克勒斯《俄狄浦斯王》：【1904/2008 考期名词】\n      是索福克勒斯的著名悲剧。以希腊神话中关于忒拜王室的故事为题材。主要表现了个人意志和命运的\n      冲突。亚里士多德认为《俄狄浦斯王》是“十全十美的悲剧”，是希腊悲剧的典范。\n         索福克勒斯：【2010 考期/2410 名词】（1）古希腊著名的悲剧作家，代表作是《俄狄浦斯王》。\n      （2）悲剧主要表现个人意志与命运的冲突，其创作标志着希腊悲剧进入成熟阶段。\n古希腊喜剧 被誉为古希腊“喜剧之父”的诗人是（阿里斯托芬）。\n ★★★★  阿里斯托芬的《阿卡奈人》是（反对战争的喜剧），《鸟》表达了阿里斯托芬的（乌托邦思想）。"
