     "h": "第二章（西方文学）中古文学",
     "c": "中古文学主要的文学形式：教会文学；骑士文学；英雄史诗和谣曲；市民文学。\n      欧洲文学史上的“中世纪文学”指的是（中世纪初期和中期的文学）。\n      中世纪欧洲表达世俗封建主感情的文学是（骑士文学）。以法国的成就最高。\n      欧洲中世纪骑士抒情诗的中心是（普罗旺斯）。最有名的骑士抒情诗是（破晓歌）。\n      欧洲中世纪前期的英雄史诗中保存最完整的一部是（《贝奥武甫》）。欧洲中世纪后期英雄史诗中最\n      有代表性的作品、中世纪法国英雄史诗的代表作是（《罗兰之歌》）。中世纪后期英雄史诗包括法国\n 教会文学\n      的《罗兰之歌》，俄罗斯的《伊戈尔远征记》，德国的《尼伯龙根之歌》，西班牙的《熙德之歌》。\n 骑士文学\n       中世纪城市文学的代表作是（《列那狐传奇》），中世纪寓言讽刺叙事诗的代表作是（《列那狐传奇》），\n 市民文学\n      《列那狐传奇》中的列那狐是（市民的典型）。\n★★★★★\n          教会文学：【1310/1810 名词】\n      （1）中世纪欧洲盛行的长期占统治地位的正统文学。  （2）题材大多取自《圣经》。\n      （3）主要是宣扬基督教教义，宣扬禁欲主义和来世主义思想。\n      （4）艺术上多采用梦幻故事的形式和象征寓意的手法。\n          骑士文学：【1504/1910/2510 名词】\n      （1）欧洲封建骑士制度的产物，世俗封建主的文学。（2）肯定对现实生活的追求。\n      （3）分为骑士抒情诗和骑士叙事诗，法国成就最高。\n          市民文学：【1404 名词】\n         （1）11 世纪随着城市的出现而产生。\n      （2）大多是民间创作，直接取材于现实，反映市民的审美情趣，强调“机智”和“乐观”。\n      （3）主要体裁有韵文故事、讽刺故事、抒情诗和市民戏剧。\n      但丁的爱情诗集《新生》所赞颂的女性是（贝雅特丽齐）。\n      《神曲》作者但丁是意大利人。《神曲》的组成部分：《地狱》、《炼狱》、《天堂》。\n      带领但丁游历地狱的古罗马诗人是维吉尔。《神曲》中带领但丁游历天堂的是（贝雅特丽齐）。\n         简述《神曲》的思想内容。【1604 简答】\n      （1）宗教性。《神曲》的结构框架和思想观念都传达着基督教的宗教意识。\n      （2）人学内涵。但丁笔下的上帝在代表了基督教的爱与信仰的同时，又代表了人间的爱与正义，在\n 但丁和\n        上帝的权威背后隐藏的是世俗原则和人性角度。\n《神曲》的\n         试述《神曲》的人学内涵。【1404 论述】\n 基本内容\n      （1）但丁笔下的上帝，代表了基督教的爱与信仰，又代表了人间的爱与正义。\n★★★★★\n      （2）其人学内涵还表现在两个主要的人物形象即维吉尔和贝雅特丽齐身上：维吉尔象征智慧和理性，\n        贝雅特丽齐则是世俗之爱与信仰之爱的结合。\n      （3）这种人类模式的设计，体现了但丁对人的本质的探索，对个体人格的肯定，对主体性的高扬。\n          简述但丁《神曲》的艺术特色：【1704/1110 简答】\n      （1）构思严谨，结构完整。 （2）象征手法。（3）虚构与写实结合。\n      （4）人物形象丰富多彩。  （5）俗语写作。"
