     "h": "第六章（西方文学）19 世纪文学（上）",
     "c": "提出“回到中世纪”口号的文学思潮是（浪漫主义）。浪漫主义文学的基本特征有：【1610 简答】\n 德国文学  （强调主观情感、推崇想象力、热爱大自然、重视民间文学、夸张对比手法）。【2504 名词】\n  ★★   浪漫主义文学思潮的理论策源地是（德国）。德国浪漫主义的主要作家有（施莱格尔兄弟、霍夫曼、\n      海涅）。德国诗人海涅的代表作是（《德国——一个冬天的童话》）。\n      称为“撒旦派”或“恶魔派”的英国诗人：拜伦、济慈、雪莱）。被恩格斯称为“天才的预言家”的\n      英国浪漫主义诗人是雪莱。“如果冬天来了，春天还会远吗？”这一著名诗句的英国诗人是（雪莱）。\n 英国文学\n      英国浪漫主义文学最初的代表是（湖畔派），代表作家（华兹华斯、柯勒律治、骚塞）。“湖畔派”\n ★★★★\n      中成就最高的诗人是（华兹华斯），主张“诗歌是强烈的情感自然流露”。\n      欧洲历史小说的创始人是（司各特），代表作（《艾凡赫》）。\n      浪漫主义法国作家（雨果、斯达尔夫人、夏多布里昂、乔治·桑、大仲马）。\n      法国浪漫主义长篇小说（《基督山伯爵》、《一个世纪儿的忏悔》、《安吉堡的磨工》）。\n 法国文学  法国浪漫主义文学的旗手是（雨果）。\n ★★★★  法国第一个写“忧郁病患者”形象（勒内）的浪漫主义作家是（夏多布里昂），代表作《阿达拉》。\n      法国小说《茶花女》的作者是（小仲马）。被称为法国的“莎士比亚”的浪漫主义作家是（缪塞），\n      代表作（《一个世纪儿的忏悔》）。发生“欧那尼决战”的国家是法国。\n      被称为美国文学之父的作家是（欧文）。被称为“美国的华尔特·司各特”的作家是詹姆斯·库珀。\n 美国文学  美国因其侦探推理小说而被誉为西方现代派文学的远祖是爱伦·坡。《红字》的作者霍桑是（美国人）。\n  ★★     19 世纪美国浪漫主义文学最伟大的诗人、美国最重要的民主诗人、创造了“自由诗体”的美国浪漫主\n      义诗人是（惠特曼），代表作也是美国浪漫主义文学的高峰之作（《草叶集》）。\n         论述拜伦《唐璜》的艺术成就。【1301 论述】\n      （1）辛辣的讽刺。如拜伦对多如牛毛的赋税的讥讽：把人生的要义归纳为“活一阵，死去，恋爱\n      和纳税”。（2）富于浪漫传奇色彩。如海上遇险遭遇人吃人的惨剧、海岛上享受爱情的欢愉、土耳其\n      宫闱内的欲海风波等。（3）诗作具有浓烈的抒情性。如《哀希腊》是《唐璜》中的最著名的抒情插曲，\n拜伦《唐璜》 表露对希腊人命运的同情。（4）采用兼叙兼议的表现手法，在第三人称的叙述中插入第一人称的谈话。\n★★★★★ （5）在格律、诗歌语言等方面进行创新，是英国诗歌史上运用口语体取得最高成就的诗篇。\n          拜伦式英雄：【2304/2510 名词】\n      （1）“拜伦式英雄”是拜伦在《东方叙事诗》中塑造的一系列形象。\n      （2）他们的共同特征是高傲、孤独、倔强、个性独特，蔑视文明，反抗现存社会制度，敢于和罪恶社\n      会进行毫不妥协的斗争。  （3）《海盗》中的主人公康拉特就很有代表性。\n         《东方叙事诗》：【1904 多选】\n        是拜伦在1813—1816 年创作的以东方故事为题材的富有浪漫主义色彩的一组传奇诗，\n      包括《异教徒》《阿比道斯的新娘》《海盗》《莱拉》《柯林斯的围攻》《巴里·西娜》。\n      雨果在流亡期间完成的长篇小说（《悲惨世界》、《海上劳工》、《笑面人》）。\n      雨果小说《九三年》最突出的内容特色是（宣扬人道主义）。法国（雨果）的浪漫主义小说代表作是\n      （《巴黎圣母院》），塑造人物有（爱斯梅哈尔达、加西莫多、克洛德、法比等）。\n         论述《巴黎圣母院》美丑对照原则的运用。【1404 简答/0910 论述】\n      （1）雨果从哲学和美学的高度，运用了美与丑、善与恶强烈对照的艺术原则，编织惊心动魄的故事情\n        节，塑造异乎寻常的人物，展现了光明与黑暗殊死搏斗的画面。\n      （2）在情节、场景方面，爱斯梅哈尔达被抢与被救、爱情幽会与被诬告判刑以及被救入圣母院与被出\n《巴黎圣母   卖杀害等悲喜强烈对照。 （3）人物形象的对照，是《巴黎圣母院》对照艺术的精髓，主要通\n院》的艺术   过人物自身的对比以及对爱情的态度构成对比表现出来。\n  特色     论述《巴黎圣母院》的艺术特色。【1710 论述】\n★★★★★ （1）运用“美丑对照原则”进行创作。   （2）恢宏的史诗性质。\n      （3）曲折离奇、跌宕引人的情节。     （4）精彩的心理描写。\n         简述《悲惨世界》的主题。【2010 考期简答】\n      （1）从人道主义出发，对劳动人民的苦难命运表示关注和同情。\n      （2）对资本主义社会的法律进行了猛烈批判。（3）对共和主义英雄和巴黎人民起义进行热情赞颂。\n      （4）宣扬了作者企图以仁爱感化、开办慈善事业解决社会矛盾的人道主义理想。\n         “美丑对照原则”：【0810 名词】雨果从哲学和美学的高度，运用了美与丑、善与恶强烈对照的\n        艺术原则，编织惊心动魄的故事情节，塑造异乎寻常的人物，展现了光明与黑暗殊死搏斗的画面。\n      被誉为“俄国文学之父”的作家是（普希金）。塑造俄国文学史上第一个“小人物”形象的作品是《驿\n      站长》【维林】。《叶甫盖尼·奥涅金》中的女主人公是达吉亚娜。\n         分析多余人叶甫盖尼·奥涅金的形象。【2210 论述/1310 名词】\n 《叶甫盖\n      （1）俄国文学史上第一个“多余人”形象，是开始觉悟的贵族青年的典型。\n尼·奥涅金》\n      （2）他厌恶上流社会，又远离人民，缺少实际工作的能力。\n的人物形象\n      （3）找不到自己生活中的位置，性格极其复杂与矛盾。\n ★★★★\n      （4）通过奥涅金的形象，反映了俄国贵族社会的腐朽和堕落，揭示了“多余人”形象的致命弱点。\n         《叶甫盖尼·奥涅金》的艺术特色。【简答/论述】\n      （1）人物与环境的典型性。  （2）鲜明的对比手法。 （3）诗体小说的独特体裁。"
