     "c": "1苏联文学中“战壕真实派”作品的有（《营请求火力支援》、《一寸土》、《最后的炮轰》、《第三颗信\n        号弹》）。苏联文学中描写战争的全景小说有（《热的雪》、《围困》、《生者与死者》）。\n      马雅可夫斯基的重要作品有（《好！》、《穿裤子的云》、《列宁》、《开会迷》）。\n 俄罗斯—\n      苏联文学中被称作“国内战争时期的英雄史诗”的作品是（《毁灭》）法捷耶夫反映国内战争的长篇小\n 苏联文学\n        说是（《毁灭》）。苏联小说《解冻》的作者是（爱伦堡）。\n ★★★\n          “战壕真实派”：【1310名词】\n      （1）“战壕真实派”是苏联50年代中期一批真实描写战地生活作家的特称。（2）代表作家有邦达列\n      夫等。 （3）其创作尽力突出战壕真实，渲染战争的残酷，突出普通人在战争中的不幸。\n      被认为从某种程度上是“新小说”先声的长篇小说的（《伪币制造者》）的作者是（安德烈·纪德）。\n 英国文学\n      20世纪英国著名作家劳伦斯大胆描写性爱，歌颂人性复归的作品是（《查泰莱夫人的情人》），\n  ★★\n      劳伦斯带有自传性质的成名作是（《儿子与情人》）。《福尔赛世家》三部曲：英国（高尔斯华绥）。\n 德语国家  “寓意剧”《四川好人》的德国作者是（布莱希特）。《一个陌生女人的来信》的作者是奥地利人（茨\n 文学★★  威格）。托马斯·曼的成名作《布登勃洛克一家》的副标题是（《一个家族的没落》）。\n      菲茨杰拉德的代表作是（《了不起的盖茨比》）。长篇小说《美国的悲剧》的作者是（德莱塞）。\n 美国文学\n       欧·亨利的主要短篇小说有（《麦琪的礼物》、《警察与赞美诗》、《最后一片藤叶》）。\n  ★★\n      “为中国题材小说作出了开拓性贡献”而获诺贝尔文学奖的美国作家是（赛珍珠）。\n      高尔基早期创作的浪漫主义短篇小说是（《伊则吉尔老婆子》）。高尔基早期描写流浪汉生活的代表\n        作是（《切尔卡什》）。自传体三部曲《童年》、《在人间》、《我的大学》的主人公（阿廖沙）。\n      世界文学史上首次塑造了无产阶级革命者的英雄形象（《母亲》），《母亲》女主人公是（尼洛夫娜）。\n 高尔基    《母亲》的问世，揭开了无产阶级文学的历史新纪元。\n ★★★  ①第一部重点写巴威尔・符拉索夫在马克思主义理论指导下和革命实践中成长的过程。\n      ②第二部通过母亲彼拉盖雅•尼洛夫娜的精神觉醒，描写人民群众在革命运动中所显示的巨大力量。\n         《母亲》的艺术特点：【选择/简答】\n      （1）艺术构思显示出传统与创新的密切结合。 （2）小说的叙事角度也富有现代性。\n      肖洛霍夫为卫国战争题材开辟新道路的小说是（《一个人的遭遇》）【“索科洛夫”】肖洛霍夫闻名\n        世界的宏伟悲剧史诗是（《静静的顿河》），长篇小说《静静的顿河》的主人公是（葛利高里），\n        男女主人公是（葛利高里、阿克西妮亚）。\n         简析葛利高里形象。【1910 简答题】\n      （1）《静静的顿河》的主人公，富有“人的魅力”。（2）勇敢善战、勤劳热情、诚实正直，同时受\n 肖洛霍夫  哥萨克落后传统和道德偏见的影响，盲目崇拜军人荣誉。（3）爱好思考，勤于探索。\n★★★★★  简述《静静的顿河》的艺术成就。【1904 简答/1310 论述】\n      （1）这是一部气势雄浑的史诗性作品，作家的笔触伸向了广阔的空间，将波澜壮阔的历史事件与丰富、\n      深邃的人物命运水乳交融。（2）小说塑造人物形象极其成功。葛利高里的形象塑造得极为鲜明，作家\n      明确表示要通过展示这个形象的“心灵的运动”来体现“人的魅力”。\n      （3）肖洛霍夫不仅描写人物感情，而且描绘其复杂而细微的心理变化。（4）描写人物，始终把他们\n      置于社会生活之中，置于大自然的背景中。在他的作品中，人、社会、自然和谐地构成一个统一体。\n罗曼·罗兰 罗曼·罗兰创作了一系列“英雄”写作传记，最著名的有《贝多芬传》【音乐家】。\n  ★★   《约翰·克利斯朵夫》鲜明的特色是音乐性，评论界公认为它是一部“音乐小说”，长河小说。\n      海明威创作的小说（《太阳照常升起》），被称为“迷惘的一代”的宣言书。将“迷惘的一代”推向\n      高峰的作品（《永别了，武器》）。海明威以西班牙内战为题材的长篇小说（《丧钟为谁而鸣》）。\n      获得诺贝尔文学奖的作品是（《老人与海》），其中“硬汉形象”/主人公是（圣地亚哥）。\n         分析《老人与海》中的圣地亚哥形象／硬汉形象。【2310 简答/2510 论述】\n      （1）海明威所塑造的“硬汉子”形象的代表。\n      （2）其性格特点是坚韧刚强，勇敢正直，在肉体上可以被打败，但在精神上绝对不可以被击垮。\n      （3）圣地亚哥坚持奋斗与抗争。体现出了硬汉的价值，维持了人的尊严和意义。硬汉子性格是海明威\n 海明威\n        对待人类命运的基本态度的体现。\n★★★★★\n         艺术特色：论述《老人与海》的象征意义。【2210 论述】\n      （1）老人圣地亚哥是硬汉子形象的代表，是人类精神的体现。老人与大鱼的关系是人类为追求美好生\n      活理想而不断奋斗精神的写照。（2）老人与大海的关系以及与鲨鱼的搏斗是人类面对不可知的生活及\n      其命运所表现出的一种积极抗争精神。（3）老人在自然王国里历经挫折而奋斗不息，象征着创作上进\n      入老年的海明威在艺术王国中的奋力拼搏。\n         艺术特色：“冰山原则”：【2404 名词】（1）海明威在《死在午后》中提出的创作主张：冰山\n        在海里移动很是庄严宏伟，是因为它只有八分之一露在水面上。（2）创作风格简约、含蓄、凝练。"
