     "c": "第六章 19世纪文学（上）\n第一节 概述——1 浪漫主义文学；2 欧美各国浪漫主义\n第二节 拜伦——1 生平与创作（拜伦式英雄）；2 《唐璜》（主题+人物+艺术成就）\n第三节 雨果——1 生平与创作（美丑对照原则，欧那尼决战）；2 《悲惨世界》（主题+人道主义）；3 《巴黎圣母院》（主题+人物+艺术特点-美丑对照）\n第四节 普希金——1 生平与创作（多余人）；2 《叶甫盖尼·奥涅金》（主题+奥涅金+艺术特点）\n（本章各节详解待续录）"
