     "h": "第二章 中古文学（章框架导图）",
     "c": "第二章　中古文学\n\n【第二章·中古文学导图（根：中古文学）】\n- 第一节 概述：背景；概况=①教会文学 ②骑士文学 ③英雄史诗与谣曲 ④市民文学；中古文学的特征\n- 第二节 但丁：生平与创作；《神曲》=简介/思想内容/人学内涵/艺术特色\n- 背景—中世纪文学：中世纪初期和中期的文学\n  - ①教会文学：欧洲长期占统治地位的正统文学，取材《圣经》；基督教义/禁欲主义/来世思想；维护封建主阶级/教会；世俗封建主的文学，骑士与贵妇肯定对现世生活的追求\n  - ②骑士文学：骑士抒情诗—普罗旺斯/牧歌/夜歌/怨歌/破晓歌（最有名）；骑士叙事诗—不列颠系统：《特里斯和伊瑟》流传最广\n  - ③英雄史诗与谣曲：早期—《贝奥武甫》流传至今最完整的早期英雄史诗；《希尔德布兰特之歌》《卡列瓦拉》埃达、萨迦；后期—法国《罗兰之歌》：后期英雄史诗中代表，爱国主义；《熙德之歌》《尼伯龙根之歌》《伊戈尔远征记》\n  - ④市民文学：谣曲—平民意识；最著名-英国\"罗宾汉谣曲\"；韵文故事/讽刺故事/抒情诗/市民戏剧；市民的审美情趣；《列那狐传奇》—城市文学的最高成就；市民的典型\n- 中古文学的特征—宗教色彩、神秘色彩、民间文学色彩、开创性"
