     "h": "第三章 文艺复兴时期文学（章框架导图）",
     "c": "第三章　文艺复兴时期文学\n\n【第三章·文艺复兴时期文学导图（根：文艺复兴时期文学）】\n- 第一节 概述：①文艺复兴/人文主义；②人文主义文学-欧洲（意大利/法国/西班牙/英国）\n- 第二节 塞万提斯：生平与创作；《堂吉诃德》\n- 第三节 莎士比亚：生平与创作；《哈姆莱特》\n- 背景—文艺复兴—资产阶级思想文化运动\n  - ①文艺复兴/人文主义：人文主义=中心思想，对\"人\"的肯定；(1)宣扬人性，反对神性。(2)提倡科学，反对蒙昧主义。(3)以个性解放反对禁欲主义。(4)主张统一，反对封建割据。人文主义文学[主潮]、民间文学和封建文学\n  - ②人文主义文学-欧洲：\n    - 意大利：但丁：《神曲》—意大利·发源地；彼特拉克：\"人文主义之父\"/《歌集》-对劳拉；薄伽丘：《十日谈》反对禁欲主义、框形结构\n    - 法国 / 西班牙 / 英国"
