     "c": "第九章 20世纪文学（上）\n第一节 概述\n[本章结构导图]\n20世纪文学上\n第一节 概述\n②欧美各国文学\n法国—长河小说\n英国—劳伦斯\n德语国家—间离效果/陌生化\n美国—《美国的悲剧》\n第二节 高尔基\n①生平和创作—《伊则吉尔老婆子》\n②《母亲》—思想内容+巴威尔形象+艺术特点\n第三节 肖洛霍夫\n①生平和创作—《一个人的遭遇》\n②《静静的顿河》—葛利高里的形象+艺术成就\n第四节 海明威\n①生平和创作—《永别了，武器》\n②《老人与海》—圣地亚哥形象+硬汉形象；艺术成就：象征意义+冰山原则\n[第一节概述分支导图]\n①俄罗斯—苏联\n白银时代—现实主义文学+各种流派纷纷登场\n\"解冻\"思潮—爱伦堡《解冻》+干预生活\n战壕真实派—真实描写战地生活+邦达列夫\n全景文学—对战争过程进行广阔的全景性描写\n②欧美国家文学\n法国—长河小说—几代人的生活与精神面貌；罗曼·罗兰\n英国—劳伦斯—《恰特莱夫人的情人、虹、恋爱中的女人》《儿子与情人》：成名作，带有自传性\n德语国家—间离效果—布莱希特：寓意剧《四川好人》；布莱希特创造的艺术方法：陌生化效果；在角色、演员和观众间制造感情上的距离\n美国—德莱塞《美国的悲剧》—年轻人追逐金色的美国梦·沉沦"
