     "h": "第二部分 东方文学·第一章 古代文学·第二节 希伯来文学（半截）",
     "c": "第二节 希伯来文学\n一、希伯来文学的历史背景\n《旧约》既是犹太教的经典，也是希伯来民族的文学总集。[2008/2410 单选]\n它与希伯来民族漫长而又多难的历史紧密相连。\n二、希伯来文学的基本内容\n（一）四个部分【2104 多选—高频多选】　　共有39卷：\n法律书：《创世记》《出埃及记》《利未记》《民数记》《申命记》：摩西五经\n历史书：10卷，《士师记》《列王记》《约书亚记》《撒母耳记》《历代志》《以斯拉记》《尼希米记》\n先知书：《以赛亚书》《以西结书》《耶利米书》《阿摩司书》《哈巴谷书》\n诗文集：《诗篇》《雅歌》《耶利米哀歌》《约伯记》（哲理诗剧）《以斯帖记》《但以理书》等，《路得记》希伯来最早独立成篇的小说。【2304 单选】\n《耶利米哀歌》简称《哀歌》，是《旧约》中最富有犹太民族特色的一首抒情长诗，相传为先知耶利米所作。\n《雅歌》又称\"歌中之歌\"，是一组热情奔放的抒情歌集，主要内容是描写青年男女之间的爱情。\n《约伯记》约成书于公元前5世纪下半叶，可视为一部哲理诗剧，也是希伯来文学中最伟大的作品之一。\n《诗篇》是《旧约》中最大的诗歌集，共收录诗歌150首，许多诗歌是假托大卫王所作，又被称为\"大卫的诗\"。\n（二）希伯来文学的基本内容：【1910 简答/2010 考期简答】\n（1）《旧约》是犹太教的经典，也是希伯来民族文学和历史的文化总集。【2410 单选】\n（2）共39卷，分为法律书、历史书、先知书和诗文集四个部分。"
