     "h": "第二部分 东方文学·第三章 近代文学·第二节 夏目漱石（半截）",
     "c": "第二节 夏目漱石\n一、生平与创作\n1.夏目漱石（1867—1916）：日本近代文学史上最杰出的代表作家之一。【2204 名词】\n2.创作：\n（1）代表作：长篇讽刺小说《我是猫》。\n（2）描写知识分子爱情的三部曲：《三四郎》《从此以后》《门》。[1201 单选]\n\"后三部曲\"：《过了春分时节》《行人》《心》。\n➢夏目漱石：【2204 名词/2504 名词】\n（1）日本近代著名现实主义作家。（2）长篇讽刺小说《我是猫》集中描写明治时期的知识分子和资本家，批判社会的黑暗和罪恶，结构独特。（3）其创作拓宽了日本近代文学的表现领域。"
