     "h": "第二部分 东方文学·第五章 当代文学·第一节 概述（续）",
     "c": "第五章 当代文学\n[当代东方文学导图]\n- 当代东方文学\n  - 指第二次世界大战结束以后的文学\n  - 特征\n    - 鲜明的政治倾向\n    - 世界各国之间的文学与文化交流日益频繁\n    - 鲜明的民族特色\n- 战后派\n  - 日本一战后登上文坛的第一批新作家\n  - 强调艺术至上，提倡文学独立于政治之外\n  - 主张作家不受政治党派和理论的束缚\n- 日本\n  - 野间宏《阴暗的图画》被公认为\"战后派\"的先声\n  - 50年代中期\"第三新人派\"作家-大江健三郎\n- 阿拉伯\n  - 纳吉布·马哈福兹：誉为埃及小说界\"金字塔\"\n- 黑非洲\n  - 桑戈尔—塞内加尔诗人，非洲现代诗歌奠基人\n  - 索因卡—尼日利亚，1986年获诺贝尔文学奖\n  - 戈迪默—南非著名白人女作家，1991年获诺奖\n[当代文学右导图]\n- 概述：当代文学特征；战后派\n- 川端康成《雪国》\n  - 川端康成—现代著名作家；成名作《伊豆的舞女》、代表作《雪国》\n  - 美学特征—刻意追求美/传统自然美、非现实的虚幻美和颓废的官能美\n  - 驹子—出身卑微，但不甘沉沦，并富有生活理想的下层妇女的典型\n  - 岛村—养尊处优、百无聊赖的有产者；悲观颓废的虚无主义者\n  - 艺术\n    - ①诗意的抒情性②日本传统与西方意识流的交融③多种手段塑造人物\n- 阿拉伯：《宫间街》《思宫街》《甘露街》\n- 纳吉布·马哈福兹\n  - 主题\n    - 反映埃及生活画面和埃及现代史的风云变幻\n    - 一个埃及商人家庭三代人的不同生活和命运\n  - 艺术\n    - 布局完整，结构独特精湛\n    - 多角度地塑造人物性格，揭示人物内在复杂的人性底蕴\n    - 现代小说的心理描写，开拓内心世界，深化人物性格\n    - 具有高度的时代性和深刻的思想性\n\n第一节 概述\n当代东方文学：指第二次世界大战结束以后的文学。\n一、当代文学特征【简答题考点】\n（1）鲜明的政治倾向。推翻帝国主义殖民统治，为民族解放与国家繁荣而斗争。\n（2）世界各国之间的文学与文化交流日益频繁。\n（3）鲜明的民族特色。　　向世界靠拢又注意保持本民族文化与文学的特点。\n二、当代文学概况\n（一）日本文学——\"战后派\"：【名词考点】\n（1）指日本一战后登上文坛的第一批新作家，以《近代文学》杂志为中心，强调艺术至上，提倡文学独立于政治之外，主张作家不受政治党派和理论的束缚。\n（2）野间宏《阴暗的图画》被公认为\"战后派\"的先声。\n（3）第二次战后派作家：三岛由纪夫、大冈升平、安部公房、堀田善卫等。\n（4）50年代中期\"第三新人派\"作家，大江健三郎《个人的体验》《万延年的足球队》\n（二）印度文学：区域文学\n（1）孟加拉语作家：班纳吉《群神》区域文学的开创者和代表作家，长篇《医疗所》。\n（2）印地语小说家：雷努，长篇小说《肮脏的区域》，新小说派—印度当代文学走向世界。\n（三）阿拉伯文学\n纳吉布·马哈福兹：誉为埃及小说界\"金字塔\"，1988年诺贝尔文学奖获得者。\n（四）黑非洲文学【2304 多选-获得诺贝尔文学奖的黑非洲作家】\n（1）桑戈尔：塞内加尔诗人，非洲现代诗歌奠基人。\"黑人性\"文艺的主要倡导者。\n（2）沃莱·索因卡：尼日利亚，1986年获诺贝尔文学奖。长篇小说代表作《解释者》。\n（3）纳丁·戈迪默：南非著名的白人女作家，1991年获得诺贝尔文学奖。长篇小说《陌生人的世界》。《已故的资产阶级世界》《大自然的运动》\n（4）桑贝内·乌斯曼：塞内加尔著名的小说家，代表作《神的儿女》。\n（5）费丁南·奥约诺：喀麦隆小说家，3部长篇小说—《家僮的一生》《老黑人和奖章》《欧洲的道路》。把揭露殖民主义的罪恶当作自己的使命，试图唤醒读者。\n（6）钦努阿·阿契贝：尼日利亚著名作家，《瓦解》《动荡》《神箭》《人民公仆》。\n1960年，由几内亚历史学家、文学家吉布里尔·塔姆希尔·尼亚奈（1932—）整理出版的《松迪亚塔》，无疑是黑非洲口头文学的优秀作品之一，具有较高的文献和文学价值。《松迪亚塔》是一部兼具神话色彩和文献价值的长篇英雄史诗，共18章。"
